import type { PowerSyncFile } from "./files.ts";

/** The schema file that adds the synced tables outside `public`. */
export function publicationFile(
  path: string,
  statement: string,
): PowerSyncFile {
  return {
    path,
    text: [
      "-- Generated by permdock powersync generate from the policy. Do not edit.",
      "-- PowerSync syncs the tables outside public only from the powersync publication.",
      statement,
      "",
    ].join("\n"),
  };
}
